const data={version:1,voice:'marin',voiceInstructions:'Warm, precise American English Biology teacher. Speak naturally. Read ecological terms, mathematical models and conservation names carefully. Use a neutral educational tone. Read every sentence completely, including the final sentence. Do not add words or summarize.',title:'Ecology and Environment',subject:'Biology',unit:10,scope:'NEET Biology Unit 10 recorded foundation against the official 2026 syllabus baseline: population interactions and attributes, birth/death rates, migration, age distribution and growth models; ecosystem components/patterns, productivity, decomposition, food webs, energy flow and ecological pyramids; biodiversity levels/patterns, importance, loss, hotspots, threatened categories and extinction, Red Data Book, in situ/ex situ conservation, biosphere reserves, parks, sanctuaries and sacred groves. Rates, stocks, units and model limitations are explicit. Further field-data interpretation, labelled graphs, population/energy budgets and mixed conservation cases remain. All ten Biology units have foundation recordings; this is availability, not exhaustive mastery or complete NEET Physics/Chemistry mapping. Original practice, not official PYQs.',sources,chapters,quiz};
function write(p,s){fs.mkdirSync(p.slice(0,p.lastIndexOf('/')),{recursive:true});fs.writeFileSync(p+'.pending',s);fs.renameSync(p+'.pending',p)}
write('app/data/neet-ecology-lecture.json',JSON.stringify(data,null,2)+'\n');write('app/neet/classes/ecology-boards.ts','// Authored by scripts/create-neet-ecology.mjs.\nexport const ecologyBoards = '+JSON.stringify(chapters.map(c=>({title:c.title,...c.board})),null,2)+' as const;\n');console.log(chapters.length,'chapters;',quiz.length,'questions; words:',chapters.map(c=>c.script.split(/\s+/).length).join(','));
